let draftExtras=emptyExtras();try{const stored=window.localStorage.getItem(extrasKey);if(stored)draftExtras=validateExtras(JSON.parse(stored));}catch{}
function seasonExtras(){return draftExtras.seasons[String(draftYear)]||{emblems:defaultEmblems(),prediction:null,result:null};}
function updateExtras(mutator){try{const next=JSON.parse(JSON.stringify(draftExtras));mutator(next);const valid=validateExtras(next);window.localStorage.setItem(extrasKey,JSON.stringify(valid));draftExtras=valid;return true;}catch(error){$('draft-tools-status').textContent='保存できませんでした。'+error.message;return false;}}
function editSeason(next){return next.seasons[String(draftYear)]??={emblems:defaultEmblems(),prediction:null,result:null};}
function emblemHtml(emblem){return `<span class="team-emblem emblem-${emblem.color}" aria-label="エンブレム ${esc(emblem.initial)} ${esc(emblem.mark)}">${esc(emblem.mark)} ${esc(emblem.initial)}</span>`;}
function playerLink(team,player,year){return `<button type="button" class="player-link" data-player-team="${esc(team)}" data-player-name="${esc(player)}" data-player-year="${year}">${esc(player)}</button>`;}
let dialogReturnFocus=null,announcementTimer=null,sharedSnapshot=null,sharedImage=null,predictionFormYear=null;
function openToolDialog(id){const dialog=$(id);dialogReturnFocus=document.activeElement;dialog.hidden=false;if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');dialog.querySelector('button')?.focus();}
