function announceDraft(army,round,pick){if(!draftExtras.animation||!pick?.name)return;const box=$('draft-announcement');$('announcement-title').textContent=`第${round+1}巡 選択希望選手`;$('announcement-player').textContent=pick.name;$('announcement-team').textContent=`${draftState.names[army]} · ${teams[pick.team]||'特別枠（MLB）'}`;box.hidden=false;if(announcementTimer&&globalThis.clearTimeout)globalThis.clearTimeout(announcementTimer);announcementTimer=globalThis.setTimeout?.(()=>{box.hidden=true;},6000);}
