$('draft-animation').addEventListener('change',()=>{const enabled=$('draft-animation').checked;if(!updateExtras(next=>{next.animation=enabled;}))$('draft-animation').checked=draftExtras.animation;else{$('settings-status').textContent='指名演出の設定を保存しました。';if(!enabled)$('draft-announcement').hidden=true;}});
