function currentDraftSnapshot(){const stats=draftDataForYear();return {year:draftYear,final:canSaveSeason(),savedAt:new Date().toISOString(),generatedAt:stats.generatedAt||data.generatedAt,names:[...draftState.names],emblems:JSON.parse(JSON.stringify(seasonExtras().emblems)),departments:draftCategories.map(cat=>({id:cat.id,totals:[0,1].map(army=>draftTotal(cat,army)),players:[0,1].map(army=>draftState.picks[cat.id][army].map(pick=>{const stat=draftValue(cat,pick);return {team:pick?.team||'',name:pick?.name||'未指名',value:stat.status==='ok'?stat.value:null,status:stat.status};}))}))};}
