 if(!validDateString(openOn)||openOn<=currentDay()||openOn>'2200-12-31'){$('draft-tools-status').textContent='開封日は明日以降の有効な日付を指定してください。';return;}
 const prediction={central:$('prediction-central').value,pacific:$('prediction-pacific').value,winner:$('prediction-winner').value,openOn,sealedAt:new Date().toISOString(),opened:false,names:[...draftState.names]};
 if(updateExtras(next=>{editSeason(next).prediction=prediction;})){$('draft-tools-status').textContent='予言封筒を封印しました。内容と開封日は変更できません。';paintDraftTools();}
