 const updates=[[settingsKey,JSON.stringify(backup.preferences)],[menuKey,String(backup.menuCollapsed)],[savedNewsKey,JSON.stringify(backup.savedNews)],...Object.entries(backup.drafts).map(([year,draft])=>['sports-desk-draft-v1-'+year,JSON.stringify(draft)])];
